from nanobrain.core.step import BaseStep


class DedupePreserveOrderStep(BaseStep):
    COMPONENT_TYPE = "dedupe_preserve_order_step"

    async def process(self, input_data: dict, **kwargs) -> dict:
        seen = set()
        unique_items = []
        for item in input_data["items"]:
            if item not in seen:
                seen.add(item)
                unique_items.append(item)
        return {"unique": unique_items}

